python3 -I -B -c "import json,os,hashlib,subprocess,zipfile; from pathlib import Path; p=json.load(open('policy/proposals/lineage-pilot-359.json')); L=json.load(open('benchmark/lineage.json')); root=Path(os.environ.get('LABVIEW_ENVIRONMENT','/resources/environment')); A={a['id']:a for a in L['artifacts']}; print('REVIEWED DIFF'); r=subprocess.run(['git','diff','--stat','4a1797ce7070f393a4e27eb12cddb97249e90488','HEAD'],capture_output=True,text=True); print(r.stdout,r.stderr); print('LOCAL RULES', [str(x) for x in Path('.').glob('**/AGENTS.md') if '.git' not in x.parts]); print('PREPARED PINS'); [(print(k,subprocess.run(['git','-C',str(root/k),'rev-parse','HEAD'],capture_output=True,text=True).stdout.strip(),v)) for k,v in L['repository_commits'].items()]; seen=set();
for d in p['decisions']:
 if d['label']!='same-lineage': continue
 print('DECISION',d['candidate_id'])
 for e in d['evidence']+d.get('xml_evidence',[]):
  aid=e['artifact']; a=A[aid]
  if aid in seen: print('OVERLAP',aid); continue
  seen.add(aid)
  if a['archive']:
   with zipfile.ZipFile(root/a['archive']) as z:
    info=z.infolist()[a['member_index']]; b=z.read(info); print('MEMBER',aid,info.filename==a['path'])
  else: b=(root/a['repository']/a['path']).read_bytes()
  print('ORIGINAL',aid,a['path'],'hash_ok',hashlib.sha256(b).hexdigest()==a['sha256'])
  if aid in [x['artifact'] for x in d['evidence']]:
   print('PROPOSAL_METADATA',all(e.get(k)==a.get(v) for k,v in [('path','path'),('archive','archive'),('member_index','member_index'),('sha256','sha256'),('save_fields','save_versions')]),'PIN',e['repository_commit']==L['repository_commits'][e['repository']]); print('SAVE_BYTES',[(s['field'],s.get('byte_offset'),s['raw_hex'],b[s['byte_offset']:s['byte_offset']+4].hex()==s['raw_hex']) for s in a['save_versions'] if s['field']=='LVSR'])
  else:
   lines=b.decode('utf-8-sig').splitlines(); n=e['line']; print('XML',n,lines[n-1]); print('XML_ROOT',lines[:2])
print('EVALUATOR'); r=subprocess.run(['python3','-I','-B','policy/evaluator/evaluate.py','--check'],capture_output=True,text=True); print('EXIT',r.returncode); print(r.stdout); print(r.stderr)
"

